package com.transportlogistics.app.fleet.payroll.adapters.configuration;
import com.fasterxml.jackson.databind.ObjectMapper;import com.transportlogistics.app.fleet.DriverLookup;import com.transportlogistics.app.fleet.DriverPayrollIntegrationPort;import com.transportlogistics.app.fleet.DriverPayrollSourcePort;import com.transportlogistics.app.fleet.payroll.application.DriverPayrollService;import com.transportlogistics.app.fleet.payroll.ports.inbound.DriverPayrollUseCase;import com.transportlogistics.app.fleet.payroll.ports.outbound.DriverPayrollStore;import com.transportlogistics.app.fleet.payroll.ports.outbound.DriverPayrollTransaction;import org.springframework.context.annotation.*;import java.time.Clock;
@Configuration class DriverPayrollConfiguration{@Bean DriverPayrollUseCase driverPayrollUseCase(DriverPayrollStore s,DriverPayrollSourcePort t,DriverLookup d,DriverPayrollIntegrationPort i,DriverPayrollTransaction tx,ObjectMapper j,Clock c){return new DriverPayrollService(s,t,d,i,tx,j,c);}}
